import React, { createContext, useState, useContext, useEffect } from 'react';
import { 
  createUserWithEmailAndPassword, 
  signInWithEmailAndPassword,
  signOut,
  onAuthStateChanged,
  sendPasswordResetEmail,
  updateProfile
} from 'firebase/auth';
import { auth, db } from '../firebase';
import { doc, setDoc, getDoc } from 'firebase/firestore';
import stripeService from '../services/stripeService';
import { showSuccess, showError } from '../components/Toast';

const AuthContext = createContext();

export const useAuth = () => useContext(AuthContext);

export const AuthProvider = ({ children }) => {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);
  const [stripeAccountStatus, setStripeAccountStatus] = useState(null);

  const register = async (email, password, nombreCompleto, pais) => {
    try {
      // 1. Crear en Firebase Auth
      const userCredential = await createUserWithEmailAndPassword(auth, email, password);
      const firebaseUser = userCredential.user;
      
      // 2. Actualizar perfil
      await updateProfile(firebaseUser, { displayName: nombreCompleto });
      
      // 3. Crear cuenta Stripe Connect para el usuario
      const stripeAccount = await stripeService.createConnectAccount(
        email, 
        nombreCompleto, 
        pais
      );
      
      // 4. Guardar datos en Firestore
      await setDoc(doc(db, 'users', firebaseUser.uid), {
        email,
        nombre: nombreCompleto,
        pais,
        stripe_account_id: stripeAccount.accountId,
        stripe_onboarding_completed: false,
        stripe_payouts_enabled: false,
        created_at: new Date().toISOString(),
        role: 'user'
      });
      
      setUser({
        uid: firebaseUser.uid,
        email: firebaseUser.email,
        displayName: nombreCompleto,
        stripeAccountId: stripeAccount.accountId,
        onboardingStatus: false,
        role: 'user'
      });
      
      showSuccess('¡Registro exitoso!');
      return { success: true };
      
    } catch (error) {
      console.error('Error en registro:', error);
      showError(error.message);
      return { success: false, error: error.message };
    }
  };

  const login = async (email, password) => {
    try {
      const userCredential = await signInWithEmailAndPassword(auth, email, password);
      const firebaseUser = userCredential.user;
      
      // Obtener datos de Firestore
      const userDoc = await getDoc(doc(db, 'users', firebaseUser.uid));
      const userData = userDoc.data();
      
      setUser({
        uid: firebaseUser.uid,
        email: firebaseUser.email,
        displayName: firebaseUser.displayName,
        stripeAccountId: userData?.stripe_account_id,
        onboardingStatus: userData?.stripe_onboarding_completed || false,
        payoutsEnabled: userData?.stripe_payouts_enabled || false,
        role: userData?.role || 'user'
      });
      
      showSuccess('Bienvenido de vuelta');
      return { success: true };
      
    } catch (error) {
      console.error('Error en login:', error);
      showError(error.message);
      return { success: false, error: error.message };
    }
  };

  const logout = async () => {
    try {
      await signOut(auth);
      setUser(null);
      showSuccess('Sesión cerrada');
      return { success: true };
    } catch (error) {
      showError(error.message);
      return { success: false, error: error.message };
    }
  };

  const resetPassword = async (email) => {
    try {
      await sendPasswordResetEmail(auth, email);
      showSuccess('Email de recuperación enviado');
      return { success: true };
    } catch (error) {
      showError(error.message);
      return { success: false, error: error.message };
    }
  };

  const checkStripeOnboarding = async () => {
    if (!user) return false;
    
    try {
      const status = await stripeService.getOnboardingStatus();
      setStripeAccountStatus(status.onboardingCompleted ? 'completed' : 'pending');
      
      // Actualizar Firestore
      if (user.uid) {
        await setDoc(doc(db, 'users', user.uid), {
          stripe_onboarding_completed: status.onboardingCompleted,
          stripe_payouts_enabled: status.payoutsEnabled
        }, { merge: true });
      }
      
      return status.onboardingCompleted && status.payoutsEnabled;
    } catch (error) {
      console.error('Error checking onboarding:', error);
      return false;
    }
  };

  const getStripeOnboardingLink = async () => {
    try {
      // Obtener el link de onboarding de la cuenta conectada
      const userDoc = await getDoc(doc(db, 'users', user.uid));
      const userData = userDoc.data();
      
      if (userData?.onboarding_link) {
        return userData.onboarding_link;
      }
      
      // Si no hay link, crear uno nuevo
      const status = await stripeService.getOnboardingStatus();
      if (status.hasStripeAccount && !status.onboardingCompleted) {
        // Stripe no proporciona una API directa para regenerar el link
        // El usuario debe ir a Stripe Connect para completar
        return `https://connect.stripe.com/express/onboarding/${userData?.stripe_account_id}`;
      }
      
      return null;
    } catch (error) {
      console.error('Error getting onboarding link:', error);
      showError('Error generando link de verificación');
      return null;
    }
  };

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, async (firebaseUser) => {
      if (firebaseUser) {
        try {
          const userDoc = await getDoc(doc(db, 'users', firebaseUser.uid));
          const userData = userDoc.data();
          
          setUser({
            uid: firebaseUser.uid,
            email: firebaseUser.email,
            displayName: firebaseUser.displayName,
            stripeAccountId: userData?.stripe_account_id,
            onboardingStatus: userData?.stripe_onboarding_completed || false,
            payoutsEnabled: userData?.stripe_payouts_enabled || false,
            role: userData?.role || 'user'
          });
          
          // Verificar onboarding de Stripe en segundo plano
          await checkStripeOnboarding();
        } catch (error) {
          console.error('Error loading user profile:', error);
          setUser({
            uid: firebaseUser.uid,
            email: firebaseUser.email,
            displayName: firebaseUser.displayName,
          });
        }
      } else {
        setUser(null);
      }
      setLoading(false);
    });

    return unsubscribe;
  }, []);

  const value = {
    user,
    loading,
    register,
    login,
    logout,
    resetPassword,
    checkStripeOnboarding,
    getStripeOnboardingLink,
    stripeAccountStatus,
  };

  return (
    <AuthContext.Provider value={value}>
      {children}
    </AuthContext.Provider>
  );
};
